# fastapi/encoders.py
from __future__ import annotations

from datetime import date, datetime, time, timedelta
from decimal import Decimal
from enum import Enum
from pathlib import Path
from typing import Any, Callable, Dict, List, Set, Tuple, Type, Union

from pydantic import BaseModel

# --------------------------------------------------------------------------- #
# Helper to detect Pydantic custom root models
# --------------------------------------------------------------------------- #
def _is_custom_root_model(obj: Any) -> bool:
    """
    Return True if ``obj`` is an instance of a Pydantic model that has exactly
    one field named ``__root__`` and no other fields.
    """
    if not isinstance(obj, BaseModel):
        return False
    # ``__fields_set__`` contains the fields that were actually set on the model.
    # For a proper custom root model there should be only ``__root__``.
    fields = obj.__fields__
    return (
        len(fields) == 1
        and "__root__" in fields
        and isinstance(getattr(obj, "__root__", None), (list, dict, str, int, float, bool, BaseModel, set, tuple, None.__class__))
    )


# --------------------------------------------------------------------------- #
# jsonable_encoder – original implementation with added root‑model support
# --------------------------------------------------------------------------- #
def jsonable_encoder(
    obj: Any,
    *,
    include: Union[Set[int], Set[str], Dict[int, Any], Dict[str, Any], None] = None,
    exclude: Union[Set[int], Set[str], Dict[int, Any], Dict[str, Any], None] = None,
    by_alias: bool = False,
    exclude_unset: bool = False,
    exclude_defaults: bool = False,
    exclude_none: bool = False,
    custom_encoder: Dict[Type[Any], Callable[[Any], Any]] | None = None,
    sqlalchemy_safe: bool = False,
    dict_encoding: bool = True,
    allow_root_model: bool = True,  # <‑‑ new flag
) -> Any:
    """
    Convert an arbitrary object to something that can be JSON‑encoded
    (e.g. by ``json.dumps``). The function is recursive and handles
    Pydantic models, dataclasses, datetime objects, etc.
    """
    # ---- Custom root model handling ---------------------------------------
    if allow_root_model and _is_custom_root_model(obj):
        # Encode the underlying ``__root__`` value recursively.
        return jsonable_encoder(
            obj.__root__,
            include=include,
            exclude=exclude,
            by_alias=by_alias,
            exclude_unset=exclude_unset,
            exclude_defaults=exclude_defaults,
            exclude_none=exclude_none,
            custom_encoder=custom_encoder,
            sqlalchemy_safe=sqlalchemy_safe,
            dict_encoding=dict_encoding,
            allow_root_model=allow_root_model,
        )

    # ---- Normal BaseModel handling -----------------------------------------
    if isinstance(obj, BaseModel):
        encoder = getattr(obj.__config__, "json_encoders", {})
        if custom_encoder:
            encoder = {**encoder, **custom_encoder}

        obj_dict = obj.dict(
            include=include,
            exclude=exclude,
            by_alias=by_alias,
            exclude_unset=exclude_unset,
            exclude_defaults=exclude_defaults,
            exclude_none=exclude_none,
        )
        return jsonable_encoder(
            obj_dict,
            custom_encoder=encoder,
            sqlalchemy_safe=sqlalchemy_safe,
            dict_encoding=dict_encoding,
            allow_root_model=allow_root_model,
        )

    # ---- Mapping (dict‑like) -------------------------------------------------
    if isinstance(obj, dict):
        return {
            jsonable_encoder(
                k,
                custom_encoder=custom_encoder,
                sqlalchemy_safe=sqlalchemy_safe,
                dict_encoding=dict_encoding,
                allow_root_model=allow_root_model,
            )
            if not isinstance(k, (str, int, float, bool, type(None)))
            else k: jsonable_encoder(
                v,
                custom_encoder=custom_encoder,
                sqlalchemy_safe=sqlalchemy_safe,
                dict_encoding=dict_encoding,
                allow_root_model=allow_root_model,
            )
            for k, v in obj.items()
        }

    # ---- Iterable (list, set, tuple) ----------------------------------------
    if isinstance(obj, (list, set, frozenset, tuple)):
        return [
            jsonable_encoder(
                i,
                custom_encoder=custom_encoder,
                sqlalchemy_safe=sqlalchemy_safe,
                dict_encoding=dict_encoding,
                allow_root_model=allow_root_model,
            )
            for i in obj
        ]

    # ---- Primitive types ----------------------------------------------------
    if isinstance(obj, (str, int, float, bool, type(None))):
        return obj

    # ---- datetime, date, time, timedelta ------------------------------------
    if isinstance(obj, (datetime, date, time, timedelta)):
        return obj.isoformat()

    # ---- Decimal -------------------------------------------------------------
    if isinstance(obj, Decimal):
        return float(obj)

    # ---- Enum ----------------------------------------------------------------
    if isinstance(obj, Enum):
        return obj.value

    # ---- Path ----------------------------------------------------------------
    if isinstance(obj, Path):
        return str(obj)

    # ---- Custom encoders -----------------------------------------------------
    if custom_encoder:
        for typ, enc in custom_encoder.items():
            if isinstance(obj, typ):
                return enc(obj)

    # ---- Fallback – return as‑is (might raise later) -------------------------
    return obj
