# tests/test_root_model.py
import pytest
from fastapi import FastAPI
from fastapi.testclient import TestClient
from pydantic import BaseModel
from typing import List


class RootListModel(BaseModel):
    __root__: List[str]


class SubModel(BaseModel):
    name: str
    value: int


class RootNestedModel(BaseModel):
    __root__: List[SubModel]


app = FastAPI()


@app.get("/root", response_model=RootListModel)
def get_root():
    return RootListModel(__root__=["a", "b", "c"])


@app.get("/regular")
def get_regular():
    return {"msg": "hello"}


@app.get("/nested", response_model=RootNestedModel)
def get_nested():
    return RootNestedModel(
        __root__=[SubModel(name="first", value=1), SubModel(name="second", value=2)]
    )


client = TestClient(app)


def test_root_model_response():
    response = client.get("/root")
    assert response.status_code == 200
    assert response.json() == ["a", "b", "c"]  # no __root__ wrapper


def test_regular_endpoint():
    response = client.get("/regular")
    assert response.status_code == 200
    assert response.json() == {"msg": "hello"}


def test_root_model_schema():
    schema = app.openapi()
    # locate the /root path schema
    root_schema = next(
        path["responses"]["200"]["content"]["application/json"]["schema"]
        for path in schema["paths"].values()
        if "/root" in path
    )
    assert root_schema == {"type": "array", "items": {"type": "string"}}


def test_nested_root_model():
    response = client.get("/nested")
    assert response.status_code == 200
    assert response.json() == [
        {"name": "first", "value": 1},
        {"name": "second", "value": 2},
    ]


def test_allow_root_model_flag():
    from fastapi.encoders import jsonable_encoder

    model = RootListModel(__root__=["x", "y"])
    # default behaviour – unwrap
    assert jsonable_encoder(model) == ["x", "y"]
    # disabled – original dict representation
    assert jsonable_encoder(model, allow_root_model=False) == {"__root__": ["x", "y"]}
